  out.m_shadow->setAngle(0.0f);
  unsigned c=m_color?m_color:player->m_color;
  out.m_shadow->setColor((int)c);
  out.m_shadow->setPosition(pos);
  if(radius>110.0f) out.m_shadow->at64=true;
